import { describe, expect, it } from "vitest";
import { deriveBookPageV3, deriveEventShardV3, deriveSeatShardV3 } from "./v3-pdas";

// Golden vectors generated by the public client ABI's web3.js PDA helpers.
// They keep the Worker-native @solana/kit implementation byte-for-byte
// compatible without importing web3.js into the Workers bundle.
const CORE = "11111111111111111111111111111111";

describe("Worker V3 PDA facade", () => {
  it("matches the public client PDA vectors", async () => {
    await expect(deriveBookPageV3(CORE, 1, 8)).resolves.toBe("A2jrG9fNP2GitPCmpdwkd4etxWcCAQ5KTdcnsW4opjYE");
    await expect(deriveSeatShardV3(CORE, 3)).resolves.toBe("DB5NyVDVeswfNis1dHvdQWDWjTckmGes7sFsMEb5LPXC");
    await expect(deriveEventShardV3(CORE, 3)).resolves.toBe("Hn47LRZLa63muNELbkB9EXzz59dZ8LiV7GtUrdsoSob4");
  });

  it("rejects caller-controlled invalid shard indexes", async () => {
    await expect(deriveBookPageV3(CORE, 0, 9)).rejects.toThrow("invalid V3 book page");
    await expect(deriveSeatShardV3(CORE, 4)).rejects.toThrow("invalid V3 seat shard");
    await expect(deriveEventShardV3(CORE, -1)).rejects.toThrow("invalid V3 event shard");
  });
});
